insert into public.chart_of_the_week (title, description, active, video_url, poster_url, link_url, source, starts_at)
values
  ('The weight of debt', 'Government gross debt as a share of GDP, 2001–2030. France went from 59% in 2001 to a projected 123% in 2030; the United States from 54% to 141%. Japan peaked above 200%.', false, '/gazette/figures/debt.mp4', '/gazette/figures/debt.jpg', null, 'IMF, World Economic Outlook (2025–2030: projections)', '2026-11-13 00:00:00 Europe/Paris'),
  ('The world in 2100', 'The five most populous countries in 2100, from 1950. India leads; Pakistan, Nigeria and DR Congo join the top five. Nigeria grows from 37 million people in 1950 to a projected 477 million.', false, '/gazette/figures/world-2100.mp4', '/gazette/figures/world-2100.jpg', '/rankings/population-un-wpp', 'United Nations, World Population Prospects 2024 (2024–2100: projections)', '2026-11-20 00:00:00 Europe/Paris'),
  ('200 years of wealth', 'GDP per capita since 1820. Britain led the world in 1820; the United States took over, Japan caught up after 1950, and China multiplied its income per head elevenfold after 1978.', false, '/gazette/figures/wealth-200y.mp4', '/gazette/figures/wealth-200y.jpg', '/rankings/gdp-per-capita-maddison', 'Maddison Project Database 2023', '2026-11-27 00:00:00 Europe/Paris'),
  ('Who wins the Fields Medal?', 'Fields medalists born in each country (current borders), since 1936. France ranks second in the world, tied with Russia on nine medals, behind the United States.', false, '/gazette/figures/fields.mp4', '/gazette/figures/fields.jpg', '/rankings/fields-medalists', 'International Mathematical Union · count by Statlas Research', '2026-12-04 00:00:00 Europe/Paris'),
  ('Who emits the most CO2?', 'Annual CO2 emissions since 1970. China overtook the United States in 2005 and now emits almost three times as much; India has become the third-largest emitter.', false, '/gazette/figures/co2.mp4', '/gazette/figures/co2.jpg', '/rankings/co2-emissions-total', 'World Bank (EDGAR)', '2026-12-11 00:00:00 Europe/Paris'),
  ('The end of babies?', 'Births per 1,000 people since 1960. South Korea fell from 42 to under 5, now the lowest of the five countries shown; China, Italy and Japan follow it down.', false, '/gazette/figures/births.mp4', '/gazette/figures/births.jpg', '/rankings/birth-rate', 'World Bank, World Development Indicators', '2026-12-18 00:00:00 Europe/Paris'),
  ('Who wins the Nobel Prize? (top 10)', 'The ten countries with the most Nobel laureates born on their soil (current borders), 1901–2025.', false, '/gazette/figures/nobel-top10.mp4', '/gazette/figures/nobel-top10.jpg', '/rankings/nobel-laureates', 'Nobel Foundation · count by Statlas Research', '2026-12-25 00:00:00 Europe/Paris'),
  ('The oldest countries on Earth', 'Median age since 1950, countries over one million people. Japan went from 21 to 50 years old; Italy, Hong Kong, Portugal and Greece follow.', false, '/gazette/figures/oldest.mp4', '/gazette/figures/oldest.jpg', '/rankings/median-age', 'United Nations, World Population Prospects 2024 (2024–2100: projections)', '2027-01-01 00:00:00 Europe/Paris'),
  ('Who invents the future?', 'Research and development spending as a share of GDP. Israel and South Korea are far ahead of every other country.', false, '/gazette/figures/rd.mp4', '/gazette/figures/rd.jpg', '/rankings/rd-expenditure-gdp', 'World Bank (UNESCO Institute for Statistics)', '2027-01-08 00:00:00 Europe/Paris'),
  ('Factories vs services', 'Industry as a share of GDP. France fell from 24% in 1990 to 17% today; Germany kept a quarter of its economy in industry, China more than a third.', false, '/gazette/figures/industry.mp4', '/gazette/figures/industry.jpg', '/rankings/industry-share-gdp', 'World Bank, World Development Indicators', '2027-01-15 00:00:00 Europe/Paris'),
  ('The price of war', 'Military spending as a share of GDP, top five in 2025. Ukraine went from 3.4% before the invasion to almost 40%.', false, '/gazette/figures/military.mp4', '/gazette/figures/military.jpg', '/rankings/military-expenditure-gdp-sipri', 'SIPRI Military Expenditure Database', '2027-01-22 00:00:00 Europe/Paris'),
  ('The richest countries', 'GDP per capita since 1950, the ten richest countries of over one million people in 2022, led by Qatar, Norway and Singapore.', false, '/gazette/figures/richest-top10.mp4', '/gazette/figures/richest-top10.jpg', '/rankings/gdp-per-capita-maddison', 'Maddison Project Database 2023', '2027-01-29 00:00:00 Europe/Paris');
